SELECT COUNT(DISTINCT uid) AS power_users_count FROM (
  SELECT uid FROM evt
  WHERE ts BETWEEN '2026-06-01' AND '2026-06-30'
  GROUP BY uid
  HAVING COUNT(*) >= 100
) AS power_users;

SELECT COUNT(*) AS signup_count
FROM u
WHERE created >= '2026-06-01' AND created < '2026-07-01';

-- Since event types are 1, 2, and 3, let's see if the habit categories and event names can help us identify "value moments".
-- Check habit categories from hab table sample to see if any cat or nm fields might relate to "value moments".
SELECT DISTINCT cat FROM hab;

SELECT SUM(spend) AS total_spend_june_2026
FROM fct_marketing_spend
WHERE spend_date >= '2026-06-01' AND spend_date <= '2026-06-30';
